CREATE OR REPLACE FUNCTION public.admin_save_user_details(p_user_id uuid, p_full_name text, p_phone text, p_cnic text, p_address text, p_alternative text, p_id_url text, p_id_name text, p_bill_url text, p_bill_name text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN UPDATE public.profiles SET full_name=p_full_name, phone=p_phone WHERE id=p_user_id; IF NOT FOUND THEN RAISE EXCEPTION 'User not found'; END IF; INSERT INTO public.user_details(user_id,cnic_number,permanent_address,alternative_contact,id_card_url,id_card_name,utility_bill_url,utility_bill_name) VALUES(p_user_id,p_cnic,p_address,p_alternative,p_id_url,p_id_name,p_bill_url,p_bill_name) ON CONFLICT(user_id) DO UPDATE SET cnic_number=EXCLUDED.cnic_number,permanent_address=EXCLUDED.permanent_address,alternative_contact=EXCLUDED.alternative_contact,id_card_url=EXCLUDED.id_card_url,id_card_name=EXCLUDED.id_card_name,utility_bill_url=EXCLUDED.utility_bill_url,utility_bill_name=EXCLUDED.utility_bill_name,updated_at=now(); END; $$; REVOKE ALL ON FUNCTION public.admin_save_user_details(uuid,text,text,text,text,text,text,text,text,text) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.admin_save_user_details(uuid,text,text,text,text,text,text,text,text,text) TO service_role;